/// Resolve's ordinary membership/read prefix in one borrowed descriptor
/// observation. Missing slots carry only the same raw __proto__ read that
/// has_property would perform next; no getter, watcher or native property
/// is consulted, and no value or membership survives this operation.
pub(crate) fn boxhead_scope_lookup(
    self,
    name: AvmString<'gc>,
    activation: &Activation<'_, 'gc>,
) -> crate::avm1::scope::OwnScopeLookup<'gc> {
    use crate::avm1::scope::OwnScopeLookup;

    let read = self.0.borrow();
    if !matches!(read.native, NativeObject::None | NativeObject::Array(_) | NativeObject::Function(_)) {
        return OwnScopeLookup::Special;
    }
    if let Some(property) = read.properties.get_avm(name, activation.is_case_sensitive()) {
        if property.is_virtual() || !property.allow_swf_version(activation.swf_version()) {
            return OwnScopeLookup::Present;
        }
        return OwnScopeLookup::Stored(property.data());
    }
    // Exactly proto() for these ordinary kinds: the current case rule,
    // raw descriptor data and no SWF-version or virtual-getter filtering.
    let raw_proto = read.properties
        .get_avm(istr!("__proto__"), activation.is_case_sensitive())
        .map_or(Value::Undefined, |property| property.data());
    OwnScopeLookup::Missing { raw_proto }
}

